INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, data_quality_rating, primary_data_source, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at, last_checked_at, internal_notes, intake_row, publicity_consent, claim_email) VALUES ('167e8097-68dc-41e6-9829-d5e1d1e78871', 'Miracle League of San Diego', 'adaptive_club', 'Adaptive Baseball', 'baseball', '["baseball"]', 'https://miracleleagueofsandiego.org/membership/', 'stefaniew.mlsd@gmail.com', '619.679.5552', 'San Diego', 'CA', 'California', '92101', 'United States', NULL, NULL, 'address', 'Miracle League of San Diego: organized baseball for children and adults with special needs, with buddies matched to each player. HQ: 1420 Kettner Blvd. Suite 201, San Diego, CA 92101. Home: players cross home plate every Saturday and Sunday. Coordinators: Stefanie Waszut stefaniew.mlsd@gmail.com (Bell); Sue Kauffman suek.mlsd@gmail.com (Engel Family Field / Padres Park); Noah Hauptman Noahh.mlsd@gmail.com (Competitive). Footer 619.679.5552 / Tax I.D. 20-2669967. Players must be at least five years old.', NULL, NULL, 'Players must be at least five years old. Home: children and adults with special needs.', 'high', 'Alec-approved San Diego pile 2026-08-23', 'unverified', 'unverified', 'active', 1, '2026-09-03T22:00:29.401Z', '2026-08-23T05:45:00Z', '2026-09-01T02:36:09.151Z', '2026-09-03T22:00:29.401Z', '[description] Remaining 2026 named sport clock is Fall 2026 season registration is now open: Bell Middle School, 620 Briarwood Rd., San Diego, CA 92139, Opening Day Saturday, September 12, 2026; Padres Park, 1628 Lomas Santa Fe Drive, Del Mar, CA 92014, Opening Day Saturday, September 19, 2026; Competitive Division at Padres Park begins Sunday, September 20, 2026. Schedule still reprints SPRING Season 2026 (past — kept under this parent). Chrome Copyright © 2025. A printed Fall 2026 player dollar and Fall game start/end time are not on the Membership / Schedule pages opened. One club row; do not invent a statewide California Miracle League parent. Not a City of San Diego TRS child. Distinct from San Diego Wolf Pack / San Diego Ducks / CAF. Not Adaptive Sports California (invented name).', NULL, 0, NULL);
INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, data_quality_rating, primary_data_source, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at, last_checked_at, internal_notes, intake_row, publicity_consent, claim_email) VALUES ('168f70cf-0a29-45ae-a800-8f69d00ed11c', 'New Mexico Adaptive — NM 66ers', 'adaptive_club', 'Wheelchair Basketball', 'wheelchair_basketball', '["wheelchair_basketball"]', 'https://nmadaptive.org/', NULL, '(505) 750-2123', 'Albuquerque', 'NM', 'New Mexico', '87197', 'United States', NULL, NULL, 'city', 'New Mexico Adaptive, home of the NM 66ers Wheelchair Basketball Team. Remaining 2026 path: Summer Open Gym May 15 – August 31, 2026, various gyms, Albuquerque (all ages welcome); 66ers season September 1 – December 1, 2026, official practices beginning in September for the 26/27 season. Mail: P.O. Box 70252, Albuquerque, NM, United States, 87197. Contact Call Us: (505) 750-2123. Contact has an Email Us heading with no printed address — email left blank.', NULL, NULL, 'Summer Open Gym: all ages are welcome.', 'high', 'Alec-approved New Mexico pile 2026-08-22', 'unverified', 'unverified', 'active', 1, '2026-09-03T22:00:29.401Z', '2026-08-23T04:30:00Z', '2026-09-01T02:36:06.450Z', '2026-09-03T22:00:29.401Z', '[description] Nmadaptive.org never reprints Kings. Do not add a second Kings, a second New Mexico Wheelchair Sports, or NM Atomic Power.', NULL, 0, NULL);
INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, data_quality_rating, primary_data_source, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at, last_checked_at, internal_notes, intake_row, publicity_consent, claim_email) VALUES ('18008619-c380-4ced-8af5-81b3d269eeb9', 'Sacramento Youth Soccer League TOPSoccer', 'adaptive_club', 'Adaptive Soccer', 'soccer', '["soccer"]', 'https://sysl.com/content/3229/TOPSoccer', 'sactops@gmail.com', NULL, 'Sacramento', 'CA', 'California', '95831', 'United States', NULL, NULL, 'address', 'Sacramento Youth Soccer League (SYSL) TOPSoccer: modified soccer for special-needs kids 4-21 with high-school-age Buddies. Remaining Summer/Fall 2026 playdates 9:00am-10:00am at Brookfield School, 6115 Riverside Blvd., Sacramento, CA 95831: August 30; September 6, 13, 20; October 4. Buddies arrive 8:30 and stay until 10:30am. $60 includes uniform (voucher UNIFORM26 if the player already has a uniform). No cost for Buddies and Coaches. Alta clients: POS Agreement PA2525 / voucher ALTACRC26. Questions sactops@gmail.com / SacTOPS@gmail.com.', '$60 and includes uniform. No cost for Buddies and Coaches.', 1, 'Special needs kids from 4 to 21. Buddies 13-17; coaches / adult buddies 18+.', 'high', 'Alec-approved Sacramento / Tahoe / Eastern Sierra pile 2026-08-23', 'unverified', 'unverified', 'active', 1, '2026-08-23T08:00:17.762Z', '2026-08-23T06:30:00Z', '2026-09-01T02:36:10.837Z', '2026-09-04T00:00:29.968Z', '[description] Also reprints August 16, which is past. A printed desk phone is not on the official TOPSoccer page opened. Cal North TOPSoccer list reprints Sacramento Youth Soccer League / Sacramento, CA. Distinct from Elk Grove Soccer TOPSoccer. Do not invent a statewide California TOPSoccer parent. Not Adaptive Sports California (invented name).', NULL, 0, NULL);
INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, data_quality_rating, primary_data_source, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at, last_checked_at, internal_notes, intake_row, publicity_consent, claim_email) VALUES ('1cc83f61-c490-4a38-8932-f8d51026aff7', 'Peoria Wildcats Wheelchair Basketball', 'team', 'Wheelchair Basketball', 'basketball', '["basketball"]', 'https://hisra.org/adapted-sports/', NULL, '(309) 691-1929', 'Peoria', 'IL', 'Illinois', '61615', 'United States', NULL, NULL, 'address', 'Traveling wheelchair basketball for Central Illinois. Ages 5–21. Eligibility: irreversible lower-extremity disability (examples printed: paralysis, amputation, radiological limb shortening, partial-to-full joint ankylosis or joint replacement). HISRA has wheelchairs and other adaptive equipment for athletes testing a new sport. Contact Katie at 691-1929. 8727 Pioneer Road, Peoria, IL 61615.', NULL, 1, '5–21', 'high', 'Alec-approved Illinois rest-of-state pile 2026-08-22', 'unverified', 'unverified', 'active', 1, '2026-09-04T00:00:29.968Z', '2026-08-23T03:50:00Z', '2026-09-01T02:36:01.851Z', '2026-09-04T00:00:29.968Z', '[description] Child of Heart of Illinois Special Recreation Association. Distinct from HISRA Special Olympics. Do not add a second HISRA parent.', NULL, 0, NULL);
INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, data_quality_rating, primary_data_source, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at, last_checked_at, internal_notes, intake_row, publicity_consent, claim_email) VALUES ('1d60cab4-28f9-4a3d-9b3c-32fad8756dd6', 'Miracle League of Las Vegas', 'adaptive_club', 'Adaptive Baseball', 'baseball', '["baseball"]', 'https://miracleleaguelasvegas.com/', 'Roxanne@miracleleaguelasvegas.com', '(702) 800-1072', 'Las Vegas', 'NV', 'Nevada', '89106', 'United States', NULL, NULL, 'address', 'Miracle League of Las Vegas: baseball for children and adults with cognitive and/or physical challenges at Engelstad Family Park. Ball field: Miracle League Ball Field at Engelstad Family Park, 101 S. Rancho Drive / 101 South Rancho Drive, Las Vegas, NV 89106. Remaining 2026 named sport is 2026 FALL Baseball Season Saturday, September 26th, 2026 – Saturday, November 14th, 2026. Calendar: start time for the first game each Saturday is 8:00 AM; Cactus League Competitive Division Saturday at 6PM. Jersey/hat pickup Saturday, Sept 19, 9am–2pm; official new-player Meet & Greet Saturday, Sept 12, 9am–11am. Register: registration for the 2026 FALL Baseball Season is now closed / full — wait list via Roxanne. Contact: (702) 800-1072 (PLEASE NOTE NEW PHONE #); Roxanne@miracleleaguelasvegas.com; header / Events also prints Info@MiracleLeagueLasVegas.com.', 'Register Fall 2026 prints “$25 SPRING REGISTRATION FEE” (quoted as printed on the Fall page). Player scholarships are available if the Registration Fee is a hardship. Registration closed / wait-list (full).', 1, 'Our Games / mission: children and adults with cognitive and/or physical challenges.', 'high', 'Alec-approved Nevada pile 2026-08-22', 'unverified', 'unverified', 'active', 1, '2026-09-04T00:00:29.968Z', '2026-08-23T05:15:00Z', '2026-09-01T02:36:08.756Z', '2026-09-04T00:00:29.968Z', '[description] Winter Soccer Feb 21 – March 14, 2026 is past — kept under this parent, not a second soccer row. One chapter row; do not add a second statewide Miracle League or attach this as City of Las Vegas Adaptive Recreation. Distinct from Las Vegas Silver Bandits. Distinct from Special Olympics Nevada. Not Adaptive Sports Nevada (invented name).', NULL, 0, NULL);
INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, data_quality_rating, primary_data_source, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at, last_checked_at, internal_notes, intake_row, publicity_consent, claim_email) VALUES ('20b3d6ce-b15a-44e3-8382-627e6e98c306', 'City of Provo Adaptive Swim', 'parks_recreation', 'Adaptive Swimming', 'swimming', '["swimming"]', 'https://www.provo.gov/516/Aquatic-Programs', NULL, '(801) 852-6620', 'Provo', 'UT', 'Utah', '84601', 'United States', NULL, NULL, 'address', 'Provo Parks & Recreation / Provo Recreation Center Adaptive Swim. Remaining 2026 named cards: Adaptive Swim School Fall 1 Monday and Wednesday September 21 to October 14; Adaptive Swim School Fall 2 Monday and Wednesday October 26 to November 18; Adaptive Team Saturdays September 19 to October 17, 12:00 PM to 1:00 PM. Adaptive Swim School classes are 30 minutes. Recreation Center Indoor Pool / Physical Address 320 W 500 N, Recreation Center, Provo, UT 84601; (801) 852-6620. Email blank. Summer lesson times 12:00 PM / 12:30 PM are Summer Times, not the fall clock.', 'Adaptive Swim School: $50 per resident, $60 per non-resident. Adaptive Team / year-round practice: $50 residents, $60 non-residents.', NULL, 'Adaptive Swim School and Adaptive Team: 5 to 18 years.', 'high', 'Alec-approved Utah pile 2026-08-22', 'unverified', 'unverified', 'active', 1, '2026-09-04T00:00:29.968Z', '2026-08-23T05:10:00Z', '2026-09-01T02:36:08.425Z', '2026-09-04T00:00:29.968Z', '[description] Adaptive Piranhas Swim Team 2026 June 1 to July 23 is past — not published as current. Do not add a second SOUT swim parent. Not Adaptive Sports Utah (invented name).', NULL, 0, NULL);
