INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, data_quality_rating, primary_data_source, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at, last_checked_at, internal_notes, intake_row, publicity_consent, claim_email) VALUES ('744c9a2a-6eb1-4f70-8665-5fc162348321', 'Rockford Junior Chariots', 'team', 'Wheelchair Basketball', 'basketball', '["basketball"]', 'https://uwhealthsportsfactory.com/wheelchair-basketball', 'ShannonSchumacher@rockfordparkdistrict.org', '815-987-1604', 'Rockford', 'IL', 'Illinois', '61101', 'United States', NULL, NULL, 'city', 'Junior wheelchair basketball team. 2014 NWBA Junior Division National Champions. Practices at Jr. Varsity NWBA standards; weekend tournaments during the season (October–April). Daily wheelchair use not required; permanent lower-limb limitation that prevents running, jumping, or pivoting with the same control as a non-disabled athlete. Pre-K through high school. Contact Shannon Schumacher. Practice named at UW Health Sports Factory. TR office: 401 S. Main St., Suite 108, Rockford, IL 61101.', NULL, NULL, 'Pre-K through high school', 'high', 'Alec-approved Illinois rest-of-state pile 2026-08-22', 'unverified', 'unverified', 'active', 1, '2026-08-23T03:50:00Z', '2026-08-23T03:50:00Z', '2026-09-01T02:36:01.770Z', '2026-09-04T10:00:57.941Z', '[description] Child of Rockford Park District. Not a second Rockford Park District parent. NASR is the cooperative label, not a catalog row.', NULL, 0, NULL);
INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, data_quality_rating, primary_data_source, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at, last_checked_at, internal_notes, intake_row, publicity_consent, claim_email) VALUES ('790540c8-6706-4363-8b24-bb0a7f8683aa', 'Champaign-Urbana Special Recreation', 'member', 'Special Olympics', NULL, '["basketball","bowling","softball","trackfield","volleyball","swimming","powerlifting"]', 'https://cuspecialrecreation.com/', 'cusr@champaignparks.org', '217-819-3980', 'Champaign', 'IL', 'Illinois', '61821', 'United States', NULL, NULL, 'address', 'Intergovernmental SRA of the Champaign and Urbana Park Districts (founded 1985). Year-round therapeutic recreation: Special Olympics, sport-skills and fitness, camps, after-school, trips, inclusion into member-district programs. CUSR Center, 2212 Sangamon Drive, Champaign, IL 61821. Office Mon–Fri 8am–5pm. TTY 711.', 'Resident vs non-resident (NR is 33% more). Non-residents may pay $50/year to register at the resident rate. Inclusion services at no cost. Scholarships: all programs except therapeutic horseback, overnight adult trips, and transportation.', NULL, 'Youth/teen programs generally 5–22; adult generally 14+; Special Olympics compete 8+; Young Athletes 2–7', 'high', 'Alec-approved Illinois rest-of-state pile 2026-08-22', 'unverified', 'unverified', 'active', 1, '2026-09-04T10:00:57.941Z', '2026-08-23T03:50:00Z', '2026-09-01T02:36:01.943Z', '2026-09-04T10:00:57.941Z', '[description] Not University of Illinois Adapted Varsity. Not Rolling Heat.', NULL, 0, NULL);
INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, data_quality_rating, primary_data_source, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at, last_checked_at, internal_notes, intake_row, publicity_consent, claim_email) VALUES ('79e296f4-0eb8-4628-827d-d1e88d74af48', 'AYSO Region 73 EPIC', 'adaptive_club', 'Adaptive Soccer', 'soccer', '["soccer"]', 'https://www.ayso73.org/Default.aspx?tabid=948775', 'aysoregion73uniforms@gmail.com', '661-556-2931', 'Bakersfield', 'CA', 'California', '93313', 'United States', NULL, NULL, 'address', 'AYSO Region 73 EPIC (Everyone Plays In our Community): inclusive, non-competitive soccer for people with physical and/or intellectual disabilities who may not play on mainstream teams. Remaining 2026 path is Fall 2026 Season Schedule: Game Days Saturday mornings at 8:00 AM, Bakersfield Sports Village (Kaiser Permanente), Season Dates August 26, 2026 – October 24, 2026. Region 73 Fall EPIC Program Registration Is Now Open. Office / mail: Box 371 4725 Panama Lane, Suite D3, Bakersfield, California 93313. EPIC Program Coordinator Melisia Velez aysoregion73uniforms@gmail.com; official footer region73rc@gmail.com / 661-556-2931. Players from 6 years and older; participants must be ambulatory. Regional Fee (EPIC Division) $35; AYSO National membership fee $25.00 per player; Sports Connect transaction fee $3.50; registration includes a team uniform. Team name Rainbow Skittles.', 'Regional Fee (EPIC Division) $35; AYSO National membership fee $25.00 per player (annual, non-refundable, non-transferable); Sports Connect transaction fee $3.50 per transaction (non-refundable). Registration includes a team uniform, soccer accident insurance, and a basic fall photo package.', 1, 'Players from 6 years and older. Young children to older adults. Participants must be ambulatory.', 'high', 'Alec-approved leftover Central Valley pile 2026-08-23', 'unverified', 'unverified', 'active', 1, '2026-09-04T10:00:57.941Z', '2026-08-23T06:50:00Z', '2026-09-01T02:36:11.498Z', '2026-09-04T10:00:57.941Z', '[description] Chrome reprints Bakersfield Southwest, 9001 Ashe Rd. — quote it as the named region header; a dedicated Sports Village street number is not printed on the EPIC card itself. Distinct from Special Olympics California. Distinct from Special Olympics Southern California — 2026 Kern County Softball Competition. Do not invent a statewide California EPIC / TOPSoccer parent. Not Adaptive Sports California (invented name).', NULL, 0, NULL);
