INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, data_quality_rating, primary_data_source, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at, last_checked_at, internal_notes, intake_row, publicity_consent, claim_email) VALUES ('a9c79674-9a2b-4826-9fde-cd1f21141d9c', 'SOAZ Fall Games', 'adaptive_club', 'Fall Games', NULL, '["swimming","bocce","bowling","golf"]', 'https://specialolympicsarizona.org/events/month/2026-10/', NULL, '602-230-1200', 'Surprise', 'AZ', 'Arizona', NULL, 'United States', NULL, NULL, 'city', 'October 2026 events calendar: Fall Games Friday, October 23, 2026 – Saturday, October 24, 2026, 8:00 AM–5:00 PM, Surprise, Arizona. Chapter HQ 2455 N Citrus Rd, Bldg. 64, Goodyear, AZ 85395 / 602-230-1200. Email blank (2025 organizer inbox not imported). Become an Athlete: programs are at no cost to the participants; at least 8 years old for SOAZ athletes / state games.', 'Become an Athlete: programs are at no cost to the participants.', NULL, 'Become an Athlete: at least 8 years old for SOAZ athletes / state games; Young Athletes ages 2 to 7; children and adults with intellectual disabilities.', 'high', 'Alec-approved Arizona pile 2026-08-22', 'unverified', 'unverified', 'active', 1, '2026-09-04T16:00:58.022Z', '2026-08-23T04:55:00Z', '2026-09-01T02:36:07.580Z', '2026-09-04T16:00:58.022Z', '[description] Child of already-listed Special Olympics Arizona (d8b9a8dd-ac92-4a45-abb6-8636c77e6aa5). 2026-10 card does not print a street — do not copy Surprise Stadium / 15850 N Bullard Ave from the 2025 Fall Games page. Remaining 2026 area swim / bocce / bowling / golf stay on this child / the parent. Do not add a second SOAZ or a second Scottsdale / Mesa / Yuma area parent. Do not publish the 2025 Fall Games page.', NULL, 0, NULL);
INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, data_quality_rating, primary_data_source, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at, last_checked_at, internal_notes, intake_row, publicity_consent, claim_email) VALUES ('abd81ba4-900a-4e97-ad83-c50e4ef49d67', 'Thunder Adaptive Sports', 'adaptive_club', 'Sled Hockey', 'sledhockey', '["sledhockey","cycling","trackfield"]', 'https://www.thunderadaptivesports.org/sled-hockey.html', NULL, '(309) 261-2250', 'Pekin', 'IL', 'Illinois', NULL, 'United States', NULL, NULL, 'city', 'Central Illinois nonprofit. Sports: sled hockey (first program, 2016; youth development, youth travel, adult travel); adaptive cycling (started spring 2020); wheelchair track & field (launched 2025). Recreational participation is free. Sled: Sunday afternoons in Pekin, IL. Mail: Thunder Adaptive Sports, PO Box 6, Towanda, IL 61776. Cycling meets in Bloomington-Normal (Constitution Trail; often Rosa Parks on Raab Road in Normal). Track: Saturday mornings in Tazewell County. Call Tim Kirk, (309) 261-2250. Youth and adults with a permanent physical disability and/or medical diagnosis that prevents traditional participation.', 'Recreational level is free. Travel-level athletes: CAF equipment-grant rule; hotel help if they hit 50% of practices and 66% of travel games. Adult travel: travel expenses are covered (sled page).', 1, NULL, 'high', 'Alec-approved Illinois rest-of-state pile 2026-08-22', 'unverified', 'unverified', 'active', 1, '2026-09-04T16:00:58.022Z', '2026-08-23T03:50:00Z', '2026-09-01T02:36:01.586Z', '2026-09-04T16:00:58.022Z', '[description] Not Hornets / Chicago Freeze.', NULL, 0, NULL);
