INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, data_quality_rating, primary_data_source, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at, last_checked_at, internal_notes, intake_row, publicity_consent, claim_email) VALUES ('b0edc3ed-dda2-4c3d-8c09-0ae8674512a1', 'GO Unlimited Rio Rally', 'adaptive_club', 'Adaptive Cycling', 'cycling', '["cycling"]', 'https://www.gounlimited.org/event/rio-rally-2026/', 'Info@gounlimited.org', '(505) 480-2374', 'Albuquerque', 'NM', 'New Mexico', '87184', 'United States', NULL, NULL, 'city', 'Rio Rally 2026: September 26, 8:00 am–2:00 pm, Alameda Open Space, southeast of the Alameda Bridge, Albuquerque; south on the Paseo del Bosque Trail. Ride begins 8:00 a.m. Full route ~8 miles one way / ~16 miles round trip to Bike In Coffee at Old Town Farm. Limited number of adaptive cycles available for riders with disabilities; contact in advance to reserve. Mail: P.O. Box 10717, Albuquerque, NM 87184. Contact / footer: (505) 480-2374 / Info@gounlimited.org.', NULL, 1, 'Waiver asks whether the rider is under 16 (parent/guardian block). Everyone is welcome (adaptive cycle, handcycle, bicycle, or supporting).', 'high', 'Alec-approved New Mexico pile 2026-08-22', 'unverified', 'unverified', 'active', 1, '2026-09-04T18:00:58.034Z', '2026-08-23T04:30:00Z', '2026-09-01T02:36:06.623Z', '2026-09-04T18:00:58.034Z', '[description] Child of Global Opportunities Unlimited (4809f6a6-7971-40bb-aae6-5e6523e92b8e). Event organizer line Dustin Berg / dustin@gounlimited.org / (818) 585-5594 is the event organizer, not stored as the general desk. Do not add a second GO Unlimited. Do not attach as Zia Freewheelers (0a4d2c2c).', NULL, 0, NULL);
