INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, data_quality_rating, primary_data_source, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at, last_checked_at, internal_notes, intake_row, publicity_consent, claim_email) VALUES ('b5d576e1-0050-4fd6-bce6-7485293e759f', 'Louisiana GUMBO State Fall Competitions', 'adaptive_club', 'Adaptive Track and Field', 'track_and_field', '["track_and_field","boccia"]', 'https://sites.google.com/site/louisianagumboinc/whatscooking', 'carey33452@aol.com', '(318) 452-7771', 'Pineville', 'LA', 'Louisiana', '71360', 'United States', NULL, NULL, 'city', 'Remaining 2026 named competitions: Saturday October 3, GUMBO State Governors Games (city TBA on official Registration); Saturday November 14, GUMBO State Boccia Tournament, Shreveport. What''s Cooking 2026 Events table is live. Office: 2840 Military Hwy, Pineville, LA 71360 (FAQ donate line prints 2840 A Military Hwy). Contact Pam Carey, carey33452@aol.com / (318) 452-7771. Ages 5+.', 'FAQ: no entry fees. Registration and participation are always free of charge.', NULL, 'Children and adults ages 5 and up (official home / FAQ)', 'high', 'Alec-approved Louisiana pile 2026-08-22', 'unverified', 'unverified', 'active', 1, '2026-09-04T18:00:58.034Z', '2026-08-23T04:15:00Z', '2026-09-01T02:36:04.724Z', '2026-09-04T18:00:58.034Z', '[description] Child of Louisiana GUMBO Inc – Paralympic Sport Louisiana (72e41bee). Spring 2026 regionals (Delta March 20 Bastrop; North March 27 Shreveport) are past. Do not add a second GUMBO parent. Do not import USOPC extra sports (archery, wheelchair basketball, powerlifting, tennis). Not SMCL Gumbo Bowl.', NULL, 0, NULL);
INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, data_quality_rating, primary_data_source, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at, last_checked_at, internal_notes, intake_row, publicity_consent, claim_email) VALUES ('b8d32a15-1036-4cbe-82bc-7d1e52ea2199', 'Arizona Arsenal Soccer Club TOPSoccer', 'adaptive_club', 'Adaptive Soccer', 'soccer', '["soccer"]', 'https://www.azarsenalsc.org/club/topsoccer', 'jefferypeters99@gmail.com', NULL, 'Gilbert', 'AZ', 'Arizona', '85234', 'United States', NULL, NULL, 'address', 'Arizona Arsenal Soccer Club TOPSoccer. Remaining 2026 named sport is the Fall Program at Cactus Yards, 4536 E Elliot Rd, Gilbert, AZ 85234 (indoor, climate controlled). Sessions 8/23, 8/30, 9/13, 10/4, 10/11, 10/18, 10/25, 11/1 (OFF 9/6, 9/20, 9/27), 4:00 pm–5:00 pm. Program Coordinator Jeff Peters, jefferypeters99@gmail.com. Club Contact also prints info@azarsenalsc.org. Young athletes with autism, intellectual, emotional, and/or physical disabilities; each athlete paired with a volunteer Arsenal player. Buddies must be 2016 birth year or older for the 2026 season.', '$65. Players not already in the AASC TOPSoccer Program need to purchase a uniform (COLLECTION > TOPS PROGRAM 2025-27).', NULL, 'Young athletes with autism, intellectual, emotional, and/or physical disabilities.', 'high', 'Alec-approved Arizona pile 2026-08-22', 'unverified', 'unverified', 'active', 1, '2026-09-04T18:00:58.034Z', '2026-08-23T04:55:00Z', '2026-09-01T02:36:07.339Z', '2026-09-04T18:00:58.034Z', '[description] Do not invent a statewide Arizona TOPSoccer parent. Not AZ Surf / RSL-AZ (held).', NULL, 0, NULL);
INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, data_quality_rating, primary_data_source, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at, last_checked_at, internal_notes, intake_row, publicity_consent, claim_email) VALUES ('bbe97bcb-3567-4321-a692-822693770065', 'Southern Wisconsin Sled Hockey', 'team', 'Sled Hockey', 'sledhockey', '["sledhockey"]', 'https://www.skeeterssledhockey.com/', NULL, NULL, 'Madison', 'WI', 'Wisconsin', NULL, 'United States', NULL, NULL, 'city', '501(c)(3) youth and adult sled hockey for people with physical limitations. Home rink: Madison Ice Arena. Serves Madison, Verona, Sun Prairie, Middleton, Janesville and surrounding (metro for Janesville). Mail: c/o Robert Cassiday, 320 Clarence St, Fort Atkinson, WI 53538.', NULL, 1, 'Wisconsin Tumblers ages 5–8; Wisconsin Skeeters ages 8–18; Wisconsin Sting adults', 'high', 'Alec-approved Chicago + Wisconsin piles 2026-08-22', 'unverified', 'unverified', 'active', 1, '2026-09-04T18:00:58.034Z', '2026-08-23T02:35:00Z', '2026-09-01T02:36:01.226Z', '2026-09-04T18:00:58.034Z', '[description] Distinct from WASA Admirals (Milwaukee) and Coulee Region FROST.', NULL, 0, NULL);
INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, data_quality_rating, primary_data_source, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at, last_checked_at, internal_notes, intake_row, publicity_consent, claim_email) VALUES ('bc4c5331-c6f1-4650-ac89-396f5309b4e6', 'El Paso''s Miracle League', 'adaptive_club', 'Miracle League Baseball', 'baseball', '["baseball","bowling"]', 'https://www.miracleleagueofelpaso.org/', 'sandieelp@miracleleagueofelpaso.org', '(915) 779-4770', 'El Paso', 'TX', 'Texas', '79997', 'United States', NULL, NULL, 'address', 'El Paso''s Miracle League (also prints Miracle League of El Paso). Play field: 7500 W H Burges in El Paso, Texas (Ponder Park). Mail: P O Box 972508, El Paso, Texas 79997. Contact: sandieelp@miracleleagueofelpaso.org / (915) 779-4770 (Contact also prints 915-740-1253). Other Sports bowling block also prints sandieelp@aol.com. Kickball sign-up is April and October at the Miracle League Field. Soccer is each spring one-day at Patriot Soccer Dream Arena — past as remaining fall soccer. One El Paso Miracle League row.', 'Bowling $2.50 per game; rental shoes waived. Basketball $27 per player. Kickball $27 per player, includes a t-shirt.', NULL, 'Baseball: players 5 years old and up. Other Sports (basketball / bowling / kickball / soccer): 8 years and older.', 'high', 'Alec-approved Texas rest-of-state pile 2026-08-22', 'unverified', 'unverified', 'active', 1, '2026-09-04T20:00:57.951Z', '2026-08-23T04:40:00Z', '2026-09-01T02:36:06.199Z', '2026-09-04T20:00:57.951Z', '[description] Remaining standing weekly clock this pass is bowling every Thursday night at 6:30pm at Oasis Lanes, 1660 N. Zaragosa, $2.50 per game (rental shoes waived). About still names spring and fall baseball seasons; a dated Fall 2026 first-game Saturday is not on the official pages this pass — not invented. Not a second El Paso Parks parent. Not Therapeutic Horsemanship of El Paso (5d034c54). Not Special Olympics Texas.', NULL, 0, NULL);
