INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, data_quality_rating, primary_data_source, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at, last_checked_at, internal_notes, intake_row, publicity_consent, claim_email) VALUES ('f9b13bac-147c-427e-8689-2ba728ab56b2', 'Access Mammoth — Adaptive Mountain Bike Camp', 'adaptive_club', 'Adaptive Cycling', 'cycling', '["cycling"]', 'https://accessmammoth.org/event/adaptive-mountain-bike-camp-sept-5-6/', 'info@accessmammoth.org', '760-934-0791', 'Mammoth Lakes', 'CA', 'California', '93546', 'United States', NULL, NULL, 'address', 'Operator is Access Mammoth (formerly Disabled Sports Eastern Sierra; 501(c)(3) Fed Tax ID 31-1732524). Bring your own equipment or use ours. Open to adaptive riders of all experience levels. HQ: 1 Minaret Rd, PO Box 7275, Mammoth Lakes, CA 93546; 760-934-0791; info@accessmammoth.org; © 2026.', '$500 per participant. Veterans and Active Duty Military: camp fees waived. Request a scholarship via the contact line.', 1, 'Open to adaptive riders of all experience levels.', 'high', 'Alec-approved Sacramento / Tahoe / Eastern Sierra pile 2026-08-23', 'unverified', 'unverified', 'active', 1, '2026-09-05T04:00:37.951Z', '2026-08-23T06:30:00Z', '2026-09-01T02:36:11.348Z', '2026-09-05T04:00:37.951Z', '[description] Child of already-listed Disabled Sports Eastern Sierra (cd86ffb5-16df-4f2e-a4db-4d41853a46c7). Remaining 2026 named community sport clock is Adaptive Mountain Bike Camp, September 5, 2026 – September 6, 2026, Mammoth Lakes, CA, $500 per participant, veterans/active-duty camp fees waived. A printed trailhead / bike-venue street beyond Mammoth Lakes and a session start/end time are not on the official Sept 5-6 event page opened. Keep under this child / the already-listed parent