INSERT OR IGNORE INTO programs (id, organization_id, name, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, publicity_consent, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at) VALUES ('43656adc-0198-431a-9f66-cc583d9a941f', COALESCE((SELECT id FROM organizations WHERE id = 'dc9ff168-2be9-4508-ac71-44c980ca5300'), 'a461f29b-0b89-4e17-b879-6a80e0abd101'), 'Chicago Park District Veterans Adaptive Sports', 'Adaptive Veterans Sports', NULL, '["archery","cycling","powerlifting","rowing"]', 'https://www.chicagoparkdistrict.com/programs-services-veterans', 'veterans@chicagoparkdistrict.com', NULL, 'Chicago', 'IL', 'Illinois', '60615', 0, 'United States', 41.8781, -87.6298, 'city', 'CPD Veterans Programs provide adaptive sports skill development and inclusive programming for veterans of all abilities. 2026 Valor Games sports: discus, shot put, cycling, archery, powerlifting, indoor rowing, biathlon, table tennis. Also names the February Windy City Winter Sports Clinic. Valor Games Midwest 2026: Aug 18, 9:00 AM – Aug 20, 5:00 PM.', 'All CPD Veterans Programs are free with proof of service (DD214 or license signifier). Valor Games 2026 event fee $0.00.', NULL, 'Adult', 'unverified', 'unverified', 'active', 1, '2026-09-03T18:00:58.659Z', '2026-08-23T02:30:00Z', '2026-09-01T02:36:00.292Z');
INSERT OR IGNORE INTO programs (id, organization_id, name, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, publicity_consent, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at) VALUES ('56834c1e-3de5-45fd-a67e-a8b51af29d97', COALESCE((SELECT id FROM organizations WHERE id = '4248d97d-b9a3-4d03-a738-079a98c97eeb'), 'a461f29b-0b89-4e17-b879-6a80e0abd101'), 'Operation Surf — October 2026 Central Coast week-long', 'Adaptive Surfing', 'surfing', '["surfing"]', 'https://operationsurf.org/programs/week-long/', 'info@operationsurf.org', '(805) 544-SURF', 'Avila Beach', 'CA', 'California', NULL, 0, 'United States', NULL, NULL, 'city', 'Operator is Operation Surf (based in Avila Beach; mail San Luis Obispo). General application for Fall of 2026 is OPEN. Mail PO Box 1581, San Luis Obispo, CA 93406. Desk info@operationsurf.org / (805) 544-SURF. Criteria: Active Duty, Active Reservists, or Honorably Discharged Veteran of the U.S Armed Forces; Service-Connected Injury (Visible or Invisible); Post 9/11; 1 or more combat deployments. Week-long programs open to new applicants only; 8 participants per week; all-inclusive for new participants / provided at no cost.', 'All-inclusive for new participants / provided at no cost.', 1, NULL, 'unverified', 'unverified', 'active', 1, '2026-09-04T06:00:57.988Z', '2026-08-23T06:54:00Z', '2026-09-01T02:36:12.524Z');
