INSERT OR IGNORE INTO programs (id, organization_id, name, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, publicity_consent, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at) VALUES ('82a7f083-8787-4d43-87be-23d169137a4f', COALESCE((SELECT id FROM organizations WHERE id = '529488d7-efee-4db0-84d6-cd3039bffdd6'), 'a461f29b-0b89-4e17-b879-6a80e0abd101'), 'Wasatch Adaptive Sports — Adaptive Cycling', 'Adaptive Cycling', 'cycling', '["cycling","mountain_biking"]', 'https://wasatchadaptivesports.org/participate', 'programs@wasatchadaptivesports.org', '801.834.0476', 'Murray', 'UT', 'Utah', '84107', 0, 'United States', NULL, NULL, 'address', 'Participate Fall cycling (September–October): Tuesday Liberty Park (SLC) 4:00–5:00 pm or 5:30–6:30 pm; Wednesday Dr. Roi O Hardy Park 8:00–9:30 am; Thursday Millrace Park (Taylorsville) 9:00–10:30 am or 11:00–12:30 pm; Friday Provo River Delta Gateway Park 9:00–10:30 am or 11:00–12:30 pm. Lessons 1.5 hours, $20. Remaining MTB Thursdays: Sept 10 Woodward PC Flow; Sept 17 Butterfield Canyon; Sept 24 Eagle Mountain; Oct 1 / 22 South Maple Hollow; Oct 8 Butterfield Canyon; Oct 15 Draper Cycle Park; Oct 29 Lodestone Bike Park Party Laps; Sept 3 OFF. Ladies Night cycling October 27, 5:30–7:30 PM, Millrace Park. Contact: 801.834.0476 / programs@wasatchadaptivesports.org. Murray Location: 417 W. Winchester St., Murray, UT 84107. Snowbird Location: 9385 S. Snowbird Center Dr., Snowbird, Utah, 84092-9000.', 'Cycling lesson: $20 per 1.5-hour lesson; up to 100% scholarship assistance. First booking must be at least two lessons in separate weeks.', 1, NULL, 'unverified', 'unverified', 'active', 1, '2026-09-04T12:00:58.040Z', '2026-08-23T05:10:00Z', '2026-09-01T02:36:08.509Z');
INSERT OR IGNORE INTO programs (id, organization_id, name, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, publicity_consent, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at) VALUES ('a0f995bd-577f-4743-9a09-4dd642f402a3', COALESCE((SELECT id FROM organizations WHERE id = 'ef737210-2286-4829-a0a8-0bec820cabbb'), 'a461f29b-0b89-4e17-b879-6a80e0abd101'), 'City of Reno Adaptive Recreation — Sled Hockey', 'Sled Hockey', 'sledhockey', '["sledhockey"]', 'https://reno.gov/parks-and-recreation/adaptive-recreation/adaptive-programs.php', 'WolfeA@Reno.Gov', '775-333-7765', 'Reno', 'NV', 'Nevada', '89511', 0, 'United States', NULL, NULL, 'address', 'Remaining 2026 dated card is sled hockey: official Reno Adaptive upcoming-events Sled Hockey Camp August 28–30; official Move United City of Reno chapter card USA Hockey Sled Development Camp August 28–30, 2026; official USA Hockey USAH SLED CAMP. Reno, NV. August 28–30, 2026. Play: Reno Ice, The Jennifer M. O’Neal Community Ice Arena, 15500 Wedge Pkwy, Reno, NV 89511. Adaptive Connect Summer 2026: April Wolfe, Therapeutic Recreation Specialist, WolfeA@Reno.Gov / 775-333-7765. All equipment and on-ice instruction provided. Adaptive Programs also names wheelchair pickleball / rugby / skills-and-drills September–April with no 2026 year.', 'USA Hockey Reno regional camp: $125 per player (jersey + sessions).', 1, 'Adaptive Programs / Reno Ice: participants with physical disabilities; no prior experience necessary for the city/Reno Ice community program. USA Hockey regional camp (the dated Aug 28–30 card): players must have at least 1 year of sled hockey experience and a current USA Hockey player/coach registration.', 'unverified', 'unverified', 'active', 1, '2026-09-04T16:00:58.022Z', '2026-08-23T05:15:00Z', '2026-09-01T02:36:08.995Z');
