INSERT OR IGNORE INTO programs (id, organization_id, name, sport, sport_key, sports_json, website_url, email, phone, city, state, state_name, zip, publicity_consent, country, lat, lng, geo_precision, description, cost_note, equipment_provided, ages, verification_status, verification_method, status, is_public, last_ok_at, created_at, updated_at) VALUES ('b09cef9b-be5e-4bf5-9c96-aaa9480abcc3', COALESCE((SELECT id FROM organizations WHERE id = 'a10b1e03-2223-4db7-bdd9-79a067d99f60'), 'a461f29b-0b89-4e17-b879-6a80e0abd101'), 'Kinetic Kids Fall Sports', 'Adaptive Soccer', 'soccer', '["soccer","baseball","basketball","swimming"]', 'https://kinetickidstx.org/schedule/', 'info@kinetickidstx.org', '210.748.5860', 'San Antonio', 'TX', 'Texas', '78269', 0, 'United States', NULL, NULL, 'address', 'Fall 2026 Schedule. Registration Monday, August 31, 2026 at 9pm. Remaining dated sports include Parent and Me soccer Mondays starting Sep 21, 5:45–6:15p at Classics Elite Blossom Fields, 1600 E Bitters Rd; Champions baseball Mondays starting Sep 21, 5:45–6:30p at Cibolo YMCA Sports Complex, 338 S Main St, Cibolo and Tuesdays starting Sep 22, 5:45–6:30p at SA Five Diamonds Park, 8214 S Flores; Champions basketball Mondays starting Sep 21 and Thursdays starting Sept 24; swimming Sundays starting Sept 20 / Sep 27 at Emler Swim School locations; Allstars tennis Thursdays starting Sep 17, 6:30–7:30p at Northside Tennis Center, 12045 Leslie Rd, Helotes; Allstars flag football Thursdays starting Sep 24, 6:30–7:30p at Olmos Basin Park, 651 Devine Road. Volleyball one-day Saturday Sep 12 at UTSA is the first remaining dated card. Mail: Kinetic Kids, Inc., PO Box 690993, San Antonio, TX 78269. Fall 2026 printed fees vary by class ($85.25 / $95.25 soccer and baseball; $90.25 / $95.25 basketball; $90.25 swimming; $95.25 tennis; one-day $15.25) — dollar not published as a single program fee.', NULL, NULL, 'Parent and Me: 18 months to 5 years. Champions / Allstars: ages 5–21. Allstars: physical disability or developmental disabilities who follow directions in a group setting. Champions: children who need assistance following directions or staying in line.', 'unverified', 'unverified', 'active', 1, '2026-09-04T18:00:58.034Z', '2026-08-23T04:20:00Z', '2026-09-01T02:36:05.900Z');
